INSERT INTO public.categories (id, title, slug, img_src, alt, description)
VALUES
	(1, 'Polos', 'polos', '/images/polos.jpg', 'Hombre luciendo polo azul', 'Polos exclusivos con diseños que todo desarrollador querrá lucir. Ideales para llevar el código a donde vayas.'),
	(2, 'Tazas', 'tazas', '/images/tazas.jpg', 'Tazas con diseño de código', 'Tazas que combinan perfectamente con tu café matutino y tu pasión por la programación.'),
