INSERT INTO public.products (id, title, img_src, price, description, category_id, features)
VALUES
	(1, 'Polo React', '/images/polos/polo-react.png', 2000, 'Viste tu pasión por React con estilo y comodidad en cada línea de código.', 1, '["Estampado resistente que mantiene sus colores vibrantes lavado tras lavado.", "Hecho de algodón suave que asegura comodidad y frescura.", "Costuras reforzadas para una mayor durabilidad.", "Corte moderno que se adapta perfectamente al cuerpo."]'::jsonb),
	(2, 'Polo JavaScript', '/images/polos/polo-js.png', 2000, 'Deja que tu amor por JavaScript hable a través de cada hilo de este polo.', 1, '["Logo de JavaScript bordado con precisión y detalle.", "Tela premium de algodón peinado.", "Disponible en varios colores.", "Acabado profesional con doble costura."]'::jsonb),
	(3, 'Polo Node.js', '/images/polos/polo-node.png', 2000, 'Conéctate al estilo con este polo de Node.js, tan robusto como tu código.', 1, '["Diseño minimalista con el logo de Node.js.", "Material transpirable ideal para largas sesiones de código.", "Tejido resistente a múltiples lavados.", "Etiqueta sin costuras para mayor comodidad."]'::jsonb),
	(4, 'Polo TypeScript', '/images/polos/polo-ts.png', 2000, 'Tipa tu estilo con precisión: lleva tu pasión por TypeScript en cada hilo.', 1, '["Logo de TypeScript estampado en alta calidad.", "Tejido antimanchas y duradero.", "Cuello reforzado que mantiene su forma.", "100% algodón hipoalergénico."]'::jsonb),
	(5, 'Polo Backend Developer', '/images/polos/polo-backend.png', 2500, 'Domina el servidor con estilo: viste con orgullo tu título de Backend Developer.', 1, '["Diseño exclusivo para desarrolladores backend.", "Material premium que mantiene su forma.", "Costuras reforzadas en puntos de tensión.", "Estampado de alta durabilidad."]'::jsonb),
	(6, 'Polo Frontend Developer', '/images/polos/polo-frontend.png', 2500, 'Construye experiencias con estilo: luce con orgullo tu polo de Frontend Developer.', 1, '["Diseño inspirado en elementos de UI/UX.", "Tela suave y ligera perfecta para el día a día.", "Estampado flexible que no se agrieta.", "Acabado profesional en cada detalle."]'::jsonb),
	(7, 'Polo Full-Stack Developer', '/images/polos/polo-fullstack.png', 2500, 'Domina ambos mundos con estilo: lleva tu título de FullStack Developer en cada línea de tu look.', 1, '["Diseño que representa ambos mundos del desarrollo.", "Material premium de larga duración.", "Proceso de estampado ecológico.", "Corte moderno y cómodo."]'::jsonb),
	(8, 'Polo It''s A Feature', '/images/polos/polo-feature.png', 1500, 'Cuando el bug se convierte en arte: lleva con orgullo tu polo ''It''s a feature''.', 1, '["Estampado humorístico de alta calidad.", "Algodón orgánico certificado.", "Diseño exclusivo de la comunidad dev.", "Disponible en múltiples colores."]'::jsonb),
	(9, 'Polo It Works On My Machine', '/images/polos/polo-works.png', 1500, 'El clásico del desarrollador: presume tu confianza con ''It works on my machine''.', 1, '["Frase icónica del mundo del desarrollo.", "Material durable y cómodo.", "Estampado que no se desvanece.", "Ideal para regalo entre desarrolladores."]'::jsonb),
	(10, 'Sticker JavaScript', '/images/stickers/sticker-js.png', 299, 'Muestra tu amor por JavaScript con este elegante sticker clásico.', 3, '["Vinilo de alta calidad resistente al agua", "Adhesivo duradero que no deja residuos", "Colores vibrantes que no se desvanecen", "Tamaño perfecto para laptops y dispositivos"]'::jsonb),
	(11, 'Sticker React', '/images/stickers/sticker-react.png', 249, 'Decora tus dispositivos con el icónico átomo giratorio de React.', 3, '["Vinilo de alta calidad resistente al agua", "Adhesivo duradero que no deja residuos", "Colores vibrantes que no se desvanecen", "Tamaño perfecto para laptops y dispositivos"]'::jsonb),
	(12, 'Sticker Git', '/images/stickers/sticker-git.png', 399, 'Visualiza el poder del control de versiones con este sticker de Git.', 3, '["Vinilo de alta calidad resistente al agua", "Adhesivo duradero que no deja residuos", "Colores vibrantes que no se desvanecen", "Tamaño perfecto para laptops y dispositivos"]'::jsonb),
